// Production controller. The demo controller is disabled by pina-runtime=live.
// Every financial mutation is authenticated, authorised and persisted by PHP/MySQL.
import {marketingView,publicLegalCopy,icon,logo,header,footer,btn} from './app.js';
import {$,esc,money,date,openModal,closeModal,installModalKeys} from './legacy-ui.mjs';
import {COMPANY_FIELDS} from './merchant.mjs';
let config=null,state=null,currentIssuer='',tab='overview',busy=false,pollTimer=null;
const API='/api/gift/';
async function api(path,data){const response=await fetch(API+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRFToken':config.csrf},...(data===undefined?{}:{body:JSON.stringify(data)})});let result;try{result=await response.json();}catch{throw Error('Не удалось прочитать ответ сервера. Обновите данные перед повтором операции.');}if(!response.ok)throw Object.assign(Error(result.error||result.message||'Операция не выполнена'),{status:response.status});return result;}
function status(message,error=false){const el=$('#toast');el.textContent=message;el.classList.add('show');el.setAttribute('role',error?'alert':'status');clearTimeout(el.hideTimer);el.hideTimer=setTimeout(()=>el.classList.remove('show'),6000);}
async function sync(){state=await api('state/');if(!currentIssuer&&state.issuers.length)currentIssuer=state.issuers[0].id;}
function partner(id){return config.catalog.find(p=>p.id===id);}
function cards(){return (state?.orders||[]).flatMap(order=>order.cards.map(card=>({order,card})));}
function cardLabel(o,c){if(c.refund_status==='paid')return 'Возврат выполнен';if(c.refund_status==='requested')return 'Запрошен возврат';if(o.payment_status!=='confirmed')return 'Ожидает оплаты';if(c.redemption_status==='redeemed')return 'Принята поставщиком';if(['unknown','pending'].includes(c.redemption_status))return 'Проверяем приём';if(c.issuance_status==='issued')return 'Код создан';if(['pending','unknown'].includes(c.issuance_status))return 'Проверяем создание';if(c.issuance_status==='cancelled')return 'Карта отменена';return 'Можно создать код';}
function publicPartners(){return config.catalog.map(p=>({id:p.id,name:esc(p.name),issuer:esc(p.company.name),country:esc(p.country),category:'Карты компаний',mark:'КР',color:'sage',icon:'merchant',description:esc(p.program.description||p.program.goods||'Товары и услуги зарубежной компании'),use:esc(p.program.goods||'По условиям программы')}));}
function publicClean(html){const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('.art-demo,.demo-caption,.application-note').forEach(e=>e.remove());doc.querySelectorAll('.catalog-note').forEach(e=>e.textContent='Перед оплатой проверьте эмитента, страну, срок действия и условия использования карты.');doc.querySelectorAll('.catalog-toolbar .tabs').forEach(e=>e.remove());doc.querySelectorAll('.mini-card-title small').forEach(e=>e.textContent='Пример отображения карты');doc.querySelectorAll('.merchant-entry').forEach(e=>e.href='#/merchant/company');doc.querySelectorAll('[data-action=partner]').forEach(e=>e.dataset.action='live-partner');doc.querySelectorAll('[data-action=support]').forEach(e=>{e.dataset.action='contact';});doc.querySelectorAll('a').forEach(a=>{if(a.textContent.includes('демо-кабинет'))a.innerHTML='Открыть личный кабинет '+icon('arrow');});doc.querySelectorAll('.legal-note').forEach(e=>e.textContent='Pina Market реализует карты от имени и за счёт компаний-эмитентов. Товары и услуги предоставляет выбранная компания. Условия карты и сведения об эмитенте раскрываются до оплаты.');doc.querySelectorAll('.hero-footnote,.note,.checkline span,.faq-list p').forEach(e=>{e.innerHTML=e.innerHTML.replace('В прототипе реальные реквизиты отключены.','').replace('Понимаю, что заявка демонстрационная.','').replace('Понимаю, что это демонстрация формы.','').replace('В прототипе данные остаются в этом браузере. Реальное сообщение не отправляется.','Заявка будет направлена команде Pina Market.');});doc.querySelectorAll('#merchant-form button').forEach(b=>b.innerHTML=b.innerHTML.replace('демо-заявку','заявку'));if(!config.catalog.length){const list=doc.querySelector('#partner-list');if(list)list.innerHTML='<div class="panel empty">Готовим первые программы карт.<br>Каталог откроется после подключения компаний и согласования условий.<br><a class="text-link" href="#/business">Вы поставщик? Обсудим подключение '+icon('arrow')+'</a></div>';}return doc.body.innerHTML;}
function frame(title,subtitle,content,merchant=false){const nav=merchant?[['overview','redemption','Приём карты'],['registry','orders','Реестр активаций'],['settlements','reports','Баланс и расчёты'],['company','contract','Реквизиты и договор']]:[['overview','home','Обзор'],['cards','gift-card','Мои карты'],['orders','orders','Заказы'],['support','support','Поддержка'],['docs','contract','Документы']];return `<div class="shell ${merchant?'merchant-shell':''}"><aside class="sidebar"><a class="logo" href="#/">${logo()}</a><nav class="nav" aria-label="Личный кабинет">${nav.map(([id,i,n])=>`<a href="#/${merchant?'merchant':'account'}/${id}" class="${tab===id?'active':''}">${icon(i)}<span>${n}</span></a>`).join('')}</nav><div class="side-bottom"><div class="side-box"><a href="mailto:mail@pina.market">mail@pina.market</a></div><a href="#/">На главную</a><a href="#/${merchant?'account':'merchant'}">${merchant?'Кабинет покупателя':'Кабинет поставщика'}</a>${state?.client.staff?'<a href="#/admin">Управление программой</a>':''}${btn('Выйти','logout','textbtn')}</div></aside><main class="main" id="main"><header class="topbar"><span class="crumb">${merchant?'Для бизнеса':'Личный кабинет'} / ${title}</span><a class="mobile-logo" href="#/">${logo()}</a><span class="profile"><span>${esc(state?.client.email)}<small>ID ${state?.client.id}</small></span></span></header><div class="page-head"><div><p class="eyebrow">Pina Market</p><h1>${title}</h1><p>${subtitle}</p></div><a class="btn small" href="#/catalog">Выбрать карту ${icon('arrow')}</a></div>${content}</main></div>`;}
function cardTile(o,c){const ready=o.payment_status==='confirmed'&&c.issuance_status==='not_issued'&&c.refund_status==='none';return `<article class="account-card"><div class="account-card-top"><div class="issuer-avatar sage">${icon('gift-card')}</div><div><h3>${esc(o.snapshot.name)}</h3><small>Заказ № ${o.id}</small></div></div><strong class="card-amount">${money(Number(c.nominal_minor)/100)}</strong><span class="badge">${cardLabel(o,c)}</span><div class="card-bottom">${ready?btn('Создать код','live-issue','small',c.id):c.issuance_status==='issued'&&c.redemption_status==='not_redeemed'&&c.refund_status==='none'?btn('Показать код','live-code','outline small',c.id):btn('Подробнее','live-card','outline small',c.id)}</div></article>`;}
function ordersView(){return `<div class="panel order-list">${state.orders.map(o=>`<button class="order-row" data-action="live-invoice" data-id="${o.id}"><span class="order-row-icon">${icon('orders')}</span><span class="order-row-main"><b>Заказ № ${o.id}</b><small>${esc(o.snapshot.name)} · ${date(o.created_at+'Z')}</small></span><span class="order-row-status ${o.payment_status==='confirmed'?'paid':''}">${o.payment_status==='confirmed'?'Оплата подтверждена':'Ожидает оплаты'}</span><span class="order-row-amount"><b>${money(Number(o.total_minor)/100)}</b></span>${icon('arrow')}</button>`).join('')||'<div class="empty">Пока нет заказов. Начните с выбора карты в каталоге.</div>'}</div>`;}
async function buyerView(){if(!state)await sync();let content='';if(tab==='orders')content=ordersView();else if(tab==='support')content=`<section class="panel"><h2>Обращения по картам</h2><p>Откройте нужную карту и отправьте требование на возврат. По другим вопросам: <a href="mailto:mail@pina.market">mail@pina.market</a>.</p>${state.refunds.map(r=>`<article class="claim"><h3>Обращение ${esc(r.id.slice(0,8))}</h3><span class="badge review">${esc(r.status)}</span><p>${esc(r.reason)}</p><small>Срок возврата неиспользованной предоплаты: до ${date(r.due_at+'Z')}, с учётом обязательных более коротких сроков.</small></article>`).join('')}</section>`;else if(tab==='docs')content=`<div class="doc-list">${[['terms','Публичная оферта'],['refund','Возврат'],['guarantees','Гарантии и ответственность'],['privacy','Обработка данных']].map(([id,n])=>`<a class="doc-link" href="#/legal/${id}">${n}${icon('arrow')}</a>`).join('')}</div>`;else content=`${tab==='overview'?`<section class="overview-main"><p>Ваш следующий шаг</p><h2>Оплаченные карты —<br>в вашем кабинете.</h2><span>Создайте код, когда будете готовы передать его выбранному поставщику.</span></section><div class="subhead"><h2>Ваши карты</h2></div>`:''}<div class="account-card-grid">${cards().map(({order:o,card:c})=>cardTile(o,c)).join('')||'<div class="panel empty">У вас пока нет карт. Выберите программу зарубежной компании в каталоге.</div>'}</div>${tab==='overview'?'<div class="subhead"><h2>Заказы</h2></div>'+ordersView():''}`;const title={overview:'Обзор',cards:'Мои карты',orders:'Заказы',support:'Поддержка',docs:'Документы'}[tab]||'Обзор';return frame(title,'Карты выбранных компаний, заказы и обращения',content);}
function issuerSelector(){return state.issuers.length>1?`<div class="merchant-context"><label for="live-issuer">Компания</label><select id="live-issuer">${state.issuers.map(i=>`<option value="${i.id}" ${i.id===currentIssuer?'selected':''}>${esc(i.name)}</option>`).join('')}</select></div>`:'';}
function companyForm(){const i=state.issuers.find(i=>i.id===currentIssuer),co=i?.company||{};return `<div class="merchant-company-layout"><section class="panel"><p class="eyebrow">Один рамочный договор</p><h2>Реквизиты и подключение</h2><p>Заполните сведения о компании. Документ получит номер, реквизиты обеих сторон и согласованные условия.</p><p>Статус: <b>${esc(i?.contract_status||'Реквизиты не заполнены')}</b></p>${i?`${btn('Подготовить и скачать договор','live-contract-prepare','outline full',i.id)}<p class="note">Подпись Pina Market добавляется только после её утверждения. Если она ещё не настроена, документ отмечен как проект.</p><hr><form id="live-upload" class="fields"><div class="field"><label for="live-contract-file">Подписанный договор</label><input id="live-contract-file" name="file" type="file" required accept=".pdf,.docx"></div><p class="note">PDF или DOCX до 10 МБ. После загрузки документ проверит команда Pina Market.</p><button class="btn full">Загрузить экземпляр</button><p class="form-error" role="alert" hidden></p></form>`:'<p>После сохранения реквизитов здесь появятся договор и загрузка подписанного экземпляра.</p>'}</section><form id="live-company" class="panel form-panel fields"><h2>Данные компании</h2><p class="note">Программа для поставщика в Кыргызской Республике.</p>${COMPANY_FIELDS.map(([key,n,type])=>`<div class="field"><label for="live-co-${key}">${n}</label><input id="live-co-${key}" name="${key}" type="${type}" required maxlength="500" value="${esc(co[key]||'')}" ${i?.status==='active'?'disabled':''}></div>`).join('')}<label class="checkline"><input type="checkbox" required><span>Проверил сведения. Изменения работающей программы согласуются отдельно.</span></label><button class="btn full" ${i?.status==='active'?'disabled':''}>Сохранить реквизиты</button><p class="form-error" role="alert" hidden></p></form></div>`;}
async function merchantView(){if(!state)await sync();const i=state.issuers.find(i=>i.id===currentIssuer);if(!i&&tab!=='company')tab='company';let content=issuerSelector();if(tab==='company')content+=companyForm();else if(tab==='overview')content+=`<div class="merchant-dashboard"><section class="panel redeem-panel"><p class="eyebrow">Приём карты</p><h2>Примите код<br>в счёт заказа клиента.</h2><form id="live-activate" class="fields"><div class="field"><label for="live-code">Код сертификата</label><input id="live-code" name="code" required pattern="[A-Z0-9]{20}" maxlength="20" autocomplete="off"></div><div class="field"><label for="live-buyer">ФИО покупателя</label><input id="live-buyer" name="buyer" required maxlength="180"></div><div class="field"><label for="live-reference">Номер договора или заказа</label><input id="live-reference" name="contract" required maxlength="200"></div><div class="field"><label for="live-basis">Основание</label><select id="live-basis" name="basis"><option value="advance">Аванс по договору</option><option value="order_payment">Оплата конкретного заказа</option></select></div><div class="notice">Приём карты не подтверждает передачу товара или оказание услуги.</div><button class="btn full" ${i?.status!=='active'?'disabled':''}>Проверить и принять карту</button><p class="form-error" role="alert" hidden></p></form></section><section class="panel"><h2>${esc(i.name)}</h2><p>Статус подключения: ${esc(i.status)}</p><a class="text-link" href="#/merchant/registry">Реестр принятых карт ${icon('arrow')}</a><a class="text-link" href="#/merchant/settlements">Баланс и расчёты ${icon('arrow')}</a></section></div>`;else if(tab==='registry'){const data=await api('merchant/registry/?issuerId='+currentIssuer);content+=`<div class="panel merchant-registry"><div class="table-wrap"><table><thead><tr><th>Карта</th><th>Покупатель</th><th>Договор / заказ</th><th>Номинал</th><th>Статус</th></tr></thead><tbody>${data.items.map(r=>`<tr><td>${esc(r.card_id.slice(0,8))}</td><td>${esc(r.buyer_name)}</td><td>${esc(r.contract_reference)}</td><td>${money(Number(r.nominal_minor)/100)}</td><td>${esc(r.status)}</td></tr>`).join('')||'<tr><td colspan="5">Пока нет принятых карт</td></tr>'}</tbody></table></div></div><p class="note">Показана страница реестра ${data.page}. Полные коды в реестр не включаются.</p>${btn('Скачать реестр CSV','live-registry-csv','outline')}`;}else {let data;try{data=await api('merchant/balance/?issuerId='+currentIssuer);}catch(e){content+='<div class="notice">'+esc(e.message)+'</div>';data={settlements:[]};}content+=`<section class="panel"><h2>Баланс платформы</h2><p>Фактический баланс получен с серверной стороны. Комиссия технологической платформы учитывается отдельно от банковского расчёта.</p>${balanceView(data.provider)}</section><div class="subhead"><h2>Расчёты по реестрам</h2></div>${data.settlements.map(s=>`<section class="panel settlement-confirm"><h3>Реестр ${esc(s.id.slice(0,8))}</h3><dl class="receipt"><dt>Номинал карт</dt><dd>${money(Number(s.gross_minor)/100)}</dd><dt>Вознаграждение Pina</dt><dd>${money(Number(s.agent_fee_minor)/100)}</dd><dt>Расходы финансовой организации</dt><dd>${money((Number(s.control_fee_minor)+Number(s.transfer_fee_minor))/100)}</dd><dt>К получению</dt><dd>${money(Number(s.net_minor)/100)}</dd><dt>Статус банковского расчёта</dt><dd>${esc(s.status)}</dd><dt>Сверка остатка платформы</dt><dd>${s.balance_review_status==='reconciled'?'Сверено вручную':s.balance_review_status?'Ожидает ручной сверки':'После подтверждения поступления'}</dd></dl>${s.status==='bank_credited'?btn('Подтвердить получение перевода','live-settlement-ack','',s.id):''}</section>`).join('')}`;}return frame({overview:'Приём карты',registry:'Реестр активаций',settlements:'Баланс и расчёты',company:'Реквизиты и договор'}[tab]||'Кабинет поставщика','Карта, договор и банковский расчёт учитываются отдельно',content,true);}
function balanceView(provider){const b=Array.isArray(provider?.balances)?provider.balances.find(x=>x.currency_code==='RUB'):provider;if(!b||b.balance===undefined)return '<div class="notice">Баланс платформы временно недоступен. Реестры расчётов доступны ниже.</div>';return `<div class="merchant-stat-grid"><article class="summary-stat"><span>Доступно · RUB</span><strong>${money(Number(b.balance))}</strong></article><article class="summary-stat"><span>Зарезервировано · RUB</span><strong>${money(Number(b.frozen_balance||0))}</strong></article></div>`;}
function auth(){openModal(`<div class="modal-icon">${icon('email-verified')}</div><h2>Вход и регистрация</h2><p class="intro">Пришлём одноразовую ссылку на вашу почту. Пароль не нужен.</p><form id="live-auth" class="fields"><div class="field"><label for="live-email">Email</label><input id="live-email" name="email" type="email" required maxlength="254" autocomplete="email"></div><label class="checkline"><input type="checkbox" required name="accepted"><span>Мне исполнилось 18 лет. С <a href="#/legal/terms" target="_blank" rel="noopener">публичной офертой</a> ознакомился и принимаю её условия.</span></label><label class="checkline"><input type="checkbox" required><span>Ознакомлен с <a href="#/legal/privacy" target="_blank" rel="noopener">обработкой данных</a>.</span></label><button class="btn full">Получить ссылку для входа</button><p class="form-error" role="alert" hidden></p></form>`,'Вход в Pina Market');}
async function partnerDialog(id){const p=partner(id);if(!p)throw Error('Программа недоступна');openModal(`<p class="eyebrow">Подарочная карта</p><h2>${esc(p.name)}</h2><dl class="receipt"><dt>Эмитент</dt><dd>${esc(p.company.name)}<br>${esc(p.company.address)}<br>Рег. № ${esc(p.company.reg)}<br>${esc(p.company.email)}</dd><dt>Страна</dt><dd>${esc(p.program.use_country)}</dd><dt>Выпуск по запросу</dt><dd>${esc(p.program.issue_deadline)}</dd><dt>Срок запроса</dt><dd>${esc(p.program.request_deadline)}</dd><dt>Срок действия</dt><dd>${esc(p.program.validity||String(p.program.expires_seconds/86400)+' дней')}</dd><dt>Погашение</dt><dd>${esc(p.program.redemption)}</dd><dt>Возврат</dt><dd>${esc(p.program.refund)}</dd></dl><a href="${esc(p.program.rules)}" target="_blank" rel="noopener" class="text-link">Правила программы ${icon('arrow')}</a><form id="live-order" data-issuer="${p.id}" class="fields"><div class="field"><label for="live-nominal">Номинал</label><select id="live-nominal" name="nominal">${p.program.nominals.map(n=>`<option value="${n}">${money(n/100)}</option>`).join('')}</select></div><div class="field"><label for="live-quantity">Количество карт</label><input id="live-quantity" name="quantity" type="number" required min="1" max="10" value="1"></div><label class="checkline"><input type="checkbox" required name="accepted"><span>Проверил эмитента, ограничения и условия программы. С <a href="#/legal/terms" target="_blank" rel="noopener">офертой</a> ознакомился, принимаю её и подтверждаю заказ с обязанностью оплаты. Комиссию банка за перевод, если она есть, банк сообщает отдельно.</span></label><button class="btn full" ${!config.salesEnabled?'disabled':''}>Оформить заказ с обязанностью оплаты</button><p class="form-error" role="alert" hidden></p></form>`,'Условия и заказ карты',true);}
async function invoice(id){const o=state.orders.find(o=>String(o.id)===String(id));const details=await api('orders/invoice/?orderId='+encodeURIComponent(id));openModal(`<p class="eyebrow">Заказ № ${o.id}</p><h2>Счёт на оплату карт</h2><strong class="detail-amount">${money(Number(o.total_minor)/100)}</strong><dl class="receipt">${Object.entries(details.fields).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div class="notice">${esc(details.instructions)}</div><p class="note">Код можно создать после подтверждения зачисления. Юридический момент исполнения обязанности по оплате определяется офертой и законом отдельно от банковской сверки.</p>${btn('Сохранить счёт','live-invoice-download','outline full',String(id))}`,'Счёт на оплату',true);}
async function cardDetail(id){const x=cards().find(x=>x.card.id===id);if(!x)throw Error('Карта не найдена');openModal(`<p class="eyebrow">Карта ${esc(id.slice(0,8))}</p><h2>${esc(x.order.snapshot.name)}</h2><strong class="detail-amount">${money(Number(x.card.nominal_minor)/100)}</strong><span class="badge">${cardLabel(x.order,x.card)}</span><p class="intro">Само создание кода не означает приём поставщиком; приём не подтверждает получение товара.</p>${x.order.payment_status==='pending'?btn('Открыть счёт','live-invoice','full',String(x.order.id)):''}${x.order.payment_status==='confirmed'&&x.card.refund_status==='none'?btn('Обратиться за возвратом','live-refund','outline full',id):''}<a class="text-link full" href="#/legal/refund">Условия возврата</a>`,'Информация о карте');}
async function route(){closeModal(true);clearTimeout(pollTimer);const parts=location.hash.replace(/^#\/?/,'').split('/');const page=parts[0]||'';tab=parts[1]||'overview';try{
 if(page==='verify'){const r=await api('auth/verify/',{token:parts[1]});config.csrf=r.csrf;await sync();history.replaceState(null,'','#/account');return route();}
 if(page==='legal'){const id=parts[1]||'terms';let d;if(id==='terms')d={title:'Публичная оферта',body:config.offer.content.map(i=>i.table?'<div class="table-wrap"><table>'+i.table.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c).replace(/\n/g,'<br>')+'</td>').join('')+'</tr>').join('')+'</table></div>':/^\d+\s/.test(i.text)?'<h2>'+esc(i.text)+'</h2>':'<p>'+esc(i.text)+'</p>').join('')};else if(id==='privacy')d={title:'Обработка персональных данных',body:'<p>Pina Market LLC обрабатывает email, сведения об учётной записи, заказах, банковских поступлениях и обращениях для заключения и исполнения договора, учёта и защиты прав. Для приёма карты эмитент указывает ФИО покупателя и ссылку на договор или заказ.</p><p>Поставщик получает сведения, необходимые для своей покупки и расчётов. Данные не включаются в публичный реестр. Секретные коды защищаются и доступны только в предусмотренном сценарии. Паспорт по правилам банковского перевода проверяет банк.</p><p>Расчётные подтверждения и необходимые документы хранятся в пределах применимых обязательных сроков, указанных в договоре. Вопросы об обработке и правах субъектов направляйте на mail@pina.market. Отдельные согласия запрашиваются, когда они необходимы по закону; акцепт оферты не заменяет все такие согласия.</p>'};else d=await publicLegalCopy(id);$('#app').innerHTML=header()+`<main class="wrap legal-page" id="main"><a class="back-link" href="#/">← На главную</a><h1>${d.title}</h1><article>${d.body}</article></main>`+footer();$('.legal-note').textContent='Pina Market LLC · Реализация карт от имени и за счёт эмитентов.';return;}
 if(['account','merchant','admin'].includes(page)){try{await sync();}catch(e){if(e.status===401||e.status===403){$('#app').innerHTML=publicClean(await marketingView('home',publicPartners()));auth();return;}throw e;}if(page==='admin'){if(!state.client.staff)throw Error('Недостаточно прав');$('#app').innerHTML=await adminView();}else $('#app').innerHTML=page==='merchant'?await merchantView():await buyerView();if(cards().some(x=>['pending','unknown'].includes(x.card.issuance_status)||['pending','unknown'].includes(x.card.redemption_status)))pollTimer=setTimeout(()=>{if(document.visibilityState==='visible'&&$('#modal').hidden&&!document.activeElement?.matches('input,textarea,select'))route();},10000);}
 else{$('#app').innerHTML=publicClean(await marketingView(page==='business'?'business':'home',publicPartners()));const anchor=['catalog','how','faq'].includes(page)?page:page==='business'&&parts[1]==='application'?'application':null;if(anchor)requestAnimationFrame(()=>document.getElementById(anchor)?.scrollIntoView());}
 }catch(e){$('#app').innerHTML=`<main class="wrap legal-page" id="main"><h1>Не удалось открыть страницу</h1><p>${esc(e.message)}</p>${btn('Повторить загрузку','reload','outline')}<a class="text-link" href="#/">На главную ${icon('arrow')}</a></main>`;}}
function merchantSettingsForm(m){return `<details class="panel" ${m.id==='pina'?'open':''}><summary><b>${esc(m.name)}</b> · ${m.hasApiKey?'ключ настроен':'ожидает настройки'}</summary><form class="fields admin-merchant-form" data-scope="${esc(m.id)}" autocomplete="off"><p class="note">Каждой компании принадлежат свои идентификаторы. Перед сохранением проверим доступ к точке чтением баланса. Это не открывает продажи.</p>${[['merchantId','ID мерчанта',m.merchantId],['siteId','ID торговой точки',m.siteId],['recipientLogin','Логин точки или магазин.точка',m.recipientLogin]].map(([key,title,value])=>`<div class="field"><label for="${m.id}-${key}">${title}</label><input id="${m.id}-${key}" name="${key}" required maxlength="140" value="${esc(value||'')}"></div>`).join('')}<div class="field"><label for="${m.id}-key">${m.hasApiKey?'Новый API-ключ — оставьте пустым, чтобы сохранить текущий':'API-ключ'}</label><input id="${m.id}-key" name="apiKey" type="password" autocomplete="new-password" maxlength="256" ${m.hasApiKey?'':'required'}></div><label class="checkline"><input name="identityVerified" type="checkbox" required><span>Проверил в V-DAR, что мерчант принадлежит именно этой компании.</span></label><button class="btn">Проверить и сохранить</button><p class="form-error" hidden role="alert"></p><p class="note">Ключ хранится на сервере в зашифрованном виде и не отображается повторно. ${m.verifiedAt?'Последняя проверка: '+esc(m.verifiedAt):''}</p></form></details>`;}
async function adminView(){const [d,merchants]=await Promise.all([api('admin/overview/'),api('admin/merchant-settings/')]);return frame('Управление программой','Подтверждения выполняются только после проверки документов и банковских данных',`<section class="panel"><h2>Оплата заказов</h2>${d.orders.filter(o=>o.payment_status==='pending').map(o=>`<form class="fields admin-bank-form" data-order="${o.id}"><h3>Заказ № ${o.id} · ${money(Number(o.total_minor)/100)}</h3><div class="field"><label>Банковское основание<input name="bankReference" required maxlength="150"></label></div><div class="field"><label>Фактически поступило, ₽<input name="amount" type="number" step="0.01" required></label></div><label class="checkline"><input type="checkbox" required><span>Зачисление сверено с банковскими данными.</span></label><button class="btn">Подтвердить поступление</button><p class="form-error" hidden role="alert"></p><hr></form>`).join('')||'<p>Нет заказов, ожидающих оплаты.</p>'}</section><div class="subhead"><h2>Настройки мерчантов V-DAR</h2></div>${merchants.items.map(merchantSettingsForm).join('')}<div class="subhead"><h2>Компании на подключении</h2></div><section class="panel"><p>Подпись, программа, ключи и версия договора проверяются до разрешения продаж. Операционные действия доступны через защищённый инструмент администратора из пакета развёртывания.</p>${d.issuers.map(i=>`<div class="ack-row"><b>${esc(i.name)}</b><span>${esc(i.id)} · ${esc(i.status)} · договор ${esc(i.contract_number)}</span></div>`).join('')}</section><div class="subhead"><h2>Операции для сверки</h2></div><section class="panel">${d.commands.map(c=>`<div class="ack-row"><b>${esc(c.kind)} · ${esc(c.status)}</b><small>${esc(c.id)} · ${esc(c.error_code||'')}</small></div>`).join('')||'<p>Нет незавершённых команд.</p>'}</section><div class="subhead"><h2>Обращения на возврат</h2></div><section class="panel">${d.refunds.map(r=>`<div class="claim"><b>${esc(r.id)}</b><p>${esc(r.reason)}</p><small>Срок: ${date(r.due_at+'Z')}</small></div>`).join('')}</section>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const {action,id}=b.dataset;try{
 if(action==='close')return closeModal();if(action==='auth')return auth();if(action==='reload')return route();if(action==='menu'){const n=$('.mobile-links');n.hidden=!n.hidden;b.setAttribute('aria-expanded',String(!n.hidden));return;}if(action==='live-partner')return partnerDialog(id);if(action==='contact')return openModal('<h2>Связаться с Pina Market</h2><p class="intro">По заказам и картам: <a href="mailto:mail@pina.market">mail@pina.market</a>. Поставщикам доступна форма подключения на главной странице.</p>','Контакты');if(action==='logout'){await fetch('/api/logout/',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRFToken':config.csrf},body:'{}'});state=null;location.hash='/';return;}
 if(action==='live-contract-prepare'){b.disabled=true;const r=await api('documents/prepare/',{issuerId:id});const a=document.createElement('a');a.href=r.downloadUrl;a.download='';a.click();await sync();return;}
 if(action==='live-invoice')return invoice(id);if(action==='live-card')return cardDetail(id);
 if(action==='live-issue'){openModal(`<h2>Создать код карты?</h2><p class="intro">Код предназначен только для выбранного поставщика. Передавайте его, когда будете готовы оплатить ваш заказ.</p>${btn('Создать код','live-confirm-issue','full',id)}`,'Создание кода');return;}
 if(action==='live-confirm-issue'){b.disabled=true;await api('cards/issue/',{cardId:id});closeModal();await sync();await route();status('Запрос принят. Проверяем результат создания кода.');return;}
 if(action==='live-code'){b.disabled=true;const r=await api('cards/code/?cardId='+encodeURIComponent(id));openModal(`<h2>Код вашей карты</h2><div class="code-box"><span>Передавайте только выбранному поставщику</span><code>${esc(r.code)}</code></div><p class="note">Поддержка не запрашивает ваш код.</p>`,'Код карты');return;}
 if(action==='live-refund'){openModal(`<h2>Обратиться за возвратом</h2><p class="intro">Создание кода или его приём поставщиком сами по себе не отменяют ваши законные права.</p><form id="live-refund-form" data-card="${id}" class="fields"><div class="field"><label for="live-reason">Причина</label><textarea id="live-reason" name="reason" required minlength="10" maxlength="3000"></textarea></div><button class="btn full">Отправить требование</button><p class="form-error" hidden role="alert"></p></form>`,'Возврат');return;}
 if(action==='live-invoice-download'){const x=await api('orders/invoice/?orderId='+encodeURIComponent(id)),text='Pina Market — счёт по заказу '+id+'\n'+Object.entries(x.fields).map(([k,v])=>k+': '+v).join('\n')+'\n'+x.instructions;download(new Blob([text],{type:'text/plain;charset=utf-8'}),'Pina-invoice-'+id+'.txt');return;}
 if(action==='live-registry-csv'){let rows=[],page=1;for(;page<=1000;page++){const r=await api('merchant/registry/?issuerId='+currentIssuer+'&page='+page);rows.push(...r.items);if(r.items.length<100)break;}const quote=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const csv='\ufeff'+[['Карта','Покупатель','Договор','Номинал RUB','Статус'],...rows.map(r=>[r.card_id,r.buyer_name,r.contract_reference,Number(r.nominal_minor)/100,r.status])].map(r=>r.map(quote).join(';')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),'Pina-registry.csv');return;}
 if(action==='live-settlement-ack'){openModal(`<h2>Подтвердите полученный перевод</h2><form id="live-ack-form" data-settlement="${id}" class="fields"><div class="field"><label for="live-ack-amount">Фактически получено, ₽</label><input id="live-ack-amount" name="amount" required type="number" min="0.01" step="0.01"></div><div class="field"><label for="live-ack-ref">Подтверждение банка получателя</label><input id="live-ack-ref" name="bankReference" required maxlength="150"></div><label class="checkline"><input type="checkbox" required><span>Сверил банковское поступление с реестром.</span></label><button class="btn full">Подтвердить получение</button><p class="form-error" hidden role="alert"></p></form>`,'Подтверждение расчёта');}
 }catch(err){status(err.message,true);}finally{if(b.isConnected)b.disabled=false;}});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('form'))return;e.preventDefault();if(busy)return;busy=true;const d=Object.fromEntries(new FormData(f)),button=f.querySelector('button:not([type]),button[type=submit]'),error=f.querySelector('.form-error');if(button)button.disabled=true;try{
 if(f.id==='live-auth'){const r=await api('auth/request/',{email:d.email,accepted:!!d.accepted,offerVersion:config.offer.version});openModal('<h2>Проверьте почту</h2><p class="intro">'+esc(r.message)+'</p>','Ссылка отправлена');}
 else if(f.id==='merchant-form'){const r=await api('enquiries/',{...d,consent:!!d.consent});f.reset();status(r.message);}
 else if(f.id==='live-order'){if(!state){await sync().catch(()=>{});if(!state){auth();return;}}const key=f.dataset.key||(f.dataset.key=crypto.randomUUID());const n=Number(d.quantity);if(!Number.isInteger(n)||n<1||n>10)throw Error('Выберите от 1 до 10 карт');const o=await api('orders/',{key,issuerId:f.dataset.issuer,cards:Array(n).fill(Number(d.nominal)),accepted:!!d.accepted,offerVersion:config.offer.version});await sync();closeModal();location.hash='/account/orders';await invoice(o.id);}
 else if(f.id==='live-company'){const r=await api('merchant/company/',{issuerId:currentIssuer,company:d});currentIssuer=r.issuerId;await sync();await route();status('Реквизиты сохранены. Скачайте подготовленный договор.');}
 else if(f.id==='live-upload'){const file=f.querySelector('input[type=file]').files[0];if(!file||file.size>10*1024*1024)throw Error('Загрузите файл до 10 МБ');const body=new FormData();body.set('issuerId',currentIssuer);body.set('file',file);const response=await fetch(API+'documents/upload/',{method:'POST',credentials:'same-origin',headers:{'X-CSRFToken':config.csrf},body});const r=await response.json();if(!response.ok)throw Error(r.error||'Не удалось загрузить документ');await sync();await route();status('Экземпляр получен и передан на проверку.');}
 else if(f.id==='live-activate'){await api('merchant/activate/',{...d,issuerId:currentIssuer});f.reset();status('Запрос приёма зарегистрирован. Результат появится в реестре.');location.hash='/merchant/registry';}
 else if(f.id==='live-refund-form'){await api('refunds/',{cardId:f.dataset.card,reason:d.reason});closeModal();await sync();location.hash='/account/support';status('Требование зарегистрировано.');}
 else if(f.id==='live-ack-form'){await api('merchant/settlements/ack/',{...d,settlementId:f.dataset.settlement});closeModal();await route();status('Получение перевода подтверждено. Остаток платформы будет сверен вручную.');}
 else if(f.classList.contains('admin-merchant-form')){try{await api('admin/merchant-settings/',{...d,scopeId:f.dataset.scope,identityVerified:!!d.identityVerified});}finally{f.querySelector('[name=apiKey]').value='';}await route();status('Настройки мерчанта проверены и сохранены.');}
 else if(f.classList.contains('admin-bank-form')){await api('admin/bank-confirm/',{...d,orderId:Number(f.dataset.order)});await route();status('Банковское поступление учтено.');}
 }catch(err){if(error?.isConnected){error.textContent=err.message;error.hidden=false;}else status(err.message,true);}finally{busy=false;if(button?.isConnected)button.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.id==='live-issuer'){currentIssuer=e.target.value;route();}});
window.addEventListener('hashchange',route);document.addEventListener('visibilitychange',()=>{if(document.hidden&&$('#modal code'))closeModal(true);});
installModalKeys();
try{config=await api('config/');await route();}catch(e){$('#app').innerHTML=`<main class="wrap legal-page"><h1>Pina Market</h1><p>${esc(e.message)}</p><p>Карточная программа пока недоступна. Поддержка: mail@pina.market.</p></main>`;}
